        v_p = float(assign['offroad_speed'])
        minutes = float(assign['time_minutes'])
    except Exception:
        # Missing or invalid types
        return (False, None)
    # Domain checks
    if not (isinstance(K, int) and K >= 3):
        # Need at least 3 highways to be strictly harder than seed
        return (False, None)
