    try:
        q_sq = v_h*v_h - v_p*v_p
        if q_sq <= 0:
            return (False, None)
        q = math.sqrt(q_sq) / v_p
        phi = math.atan(q)
    except Exception:
        return (False, None)
    # Wedge non-overlap condition: 2*K*phi <= 2*pi
    if phi > math.pi / K:
        # Overlapping wedges lead to a more complex case not covered by the closed-form used here
        return (False, None)
    # Enforce nontrivial extension beyond the baseline circle for difficulty
    if K * (q - phi) < 0.1:
        return (False, None)
    # Time in hours
    T = minutes / 60.0
    # Area formula for K equally spaced highways with disjoint wedges:
    # A = v_p^2 * T^2 * [ pi + K * (q - arctan(q)) ]
    area = (v_p * v_p) * (T * T) * (math.pi + K * (q - phi))
    return (True, area)


        def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
